"""Prediction endpoints.

Two sources are exposed:

* the stored history in the ``predictions`` table (``GET ""`` and ``GET /{ticker}``), and
* a **live** signal generated by the trained XGBoost model (``GET /{ticker}/live``),
  which also persists its result so the stored history stays current.
"""

import logging
from pathlib import Path

from fastapi import APIRouter, Depends, HTTPException, Query
from fastapi.concurrency import run_in_threadpool
from sqlalchemy.ext.asyncio import AsyncSession
from sqlalchemy import select

from app.db.session import get_db
from app.db.models.prediction import Prediction, SignalType
from app.schemas.prediction import PredictionOut
from app.core.dependencies import get_current_user
from app.services.recommendation.engine import StockPredictor

logger = logging.getLogger(__name__)
router = APIRouter(prefix="/predictions", tags=["predictions"])

# Absolute path so the model resolves regardless of the working directory
# uvicorn was started from.
_MODEL_PATH = Path(__file__).resolve().parents[4] / "models" / "xgboost" / "current" / "model.pkl"

# Loaded once per process and reused — deserialising the booster on every
# request would dominate the response time.
_predictor: StockPredictor | None = None


def _get_predictor() -> StockPredictor:
    """Return the process-wide predictor, loading the model on first use."""
    global _predictor
    if _predictor is None:
        p = StockPredictor(model_path=_MODEL_PATH)
        p.load_model()
        _predictor = p
        logger.info("XGBoost model loaded from %s (%d features)",
                    _MODEL_PATH, len(p.feature_columns or []))
    return _predictor


@router.get("", response_model=list[PredictionOut])
async def list_predictions(db: AsyncSession = Depends(get_db), _=Depends(get_current_user)):
    result = await db.execute(select(Prediction).order_by(Prediction.created_at.desc()))
    return result.scalars().all()


@router.get("/{ticker}/live", response_model=PredictionOut)
async def get_live_prediction(
    ticker: str,
    persist: bool = Query(default=True, description="Store the result in the predictions table"),
    db: AsyncSession = Depends(get_db),
    _=Depends(get_current_user),
):
    """Generate a fresh signal for ``ticker`` with the trained XGBoost model.

    Fetches 6 months of history, rebuilds the engineered feature set, and runs the
    model to obtain up/down probabilities and a BUY / HOLD / SELL signal. Unless
    ``persist=false`` the result is written to the ``predictions`` table so the
    stored history reflects real model output rather than seed data.
    """
    ticker = ticker.upper()

    try:
        # Model inference plus a yfinance download — both blocking, so keep them
        # off the event loop.
        result = await run_in_threadpool(lambda: _get_predictor().predict(ticker))
    except FileNotFoundError as exc:
        logger.error("model artefact missing at %s", _MODEL_PATH)
        raise HTTPException(
            status_code=503,
            detail="Prediction model is not available. Train the model first.",
        ) from exc
    except ValueError as exc:
        # Raised for unusable/insufficient data or a live/train feature mismatch.
        raise HTTPException(status_code=400, detail=str(exc)) from exc
    except Exception as exc:
        logger.exception("live prediction failed for %s", ticker)
        raise HTTPException(
            status_code=502, detail=f"Live prediction failed for {ticker}"
        ) from exc

    prediction = Prediction(
        ticker=result["ticker"],
        signal=SignalType(result["signal"]),
        confidence=result["confidence"],
        probability_up=result["probability_up"],
        probability_down=result["probability_down"],
        composite_score=int(round(result["probability_up"])),
        model_version="xgboost_v1",
    )

    if persist:
        db.add(prediction)
        await db.commit()
        await db.refresh(prediction)

    return prediction


@router.get("/{ticker}", response_model=PredictionOut)
async def get_prediction(ticker: str, db: AsyncSession = Depends(get_db), _=Depends(get_current_user)):
    result = await db.execute(
        select(Prediction)
        .where(Prediction.ticker == ticker.upper())
        .order_by(Prediction.created_at.desc())
        .limit(1)
    )
    pred = result.scalar_one_or_none()
    if pred is None:
        raise HTTPException(status_code=404, detail="No prediction found for this ticker")
    return pred
